CREATE TABLE books (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(255) NOT NULL,pub_year INT NOT NULL);
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(32) NOT NULL);
CREATE TABLE comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,book_id BIGINT NOT NULL,user_id BIGINT NOT NULL,text VARCHAR(1000) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_comments_books FOREIGN KEY(book_id) REFERENCES books(id),CONSTRAINT fk_comments_users FOREIGN KEY(user_id) REFERENCES users(id));
